import {useNavigableRef} from '@github-ui/navigable-ref'
import {lazyWithPreload} from '@github-ui/react-core/lazy-with-preload'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {Suspense, useCallback, useEffect, useState} from 'react'

import {useTopNavContext} from '../primitives/TopNav'
import type {GlobalNavUserMenuProps} from '../user-menu/GlobalNavUserMenu'
import {GlobalNavUserMenuToggle} from '../user-menu/GlobalNavUserMenuToggle'

type LazyAnchoredGlobalNavUserMenuProps = Pick<GlobalNavUserMenuProps, 'owner'>

export function LazyAnchoredGlobalNavUserMenu({owner}: LazyAnchoredGlobalNavUserMenuProps) {
  const [open, setOpen] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const anchorRef = useNavigableRef<HTMLButtonElement>()
  const {getPayloadsUrl} = useTopNavContext()
  const payloadsUrl = getPayloadsUrl('user_menu')

  const {data: globalUserMenuProps, isPending} = useQuery({
    queryKey: ['global-user-menu', payloadsUrl],
    queryFn: async () => {
      const response = await verifiedFetchJSON(payloadsUrl)

      if (response.ok) {
        try {
          return (await response.json()) as GlobalNavUserMenuProps
        } catch {
          throw new Error('Failed to parse nav menu payload.')
        }
      }
      throw new Error('Failed to retrieve nav menu payload.')
    },
  })

  useEffect(() => {
    // Prevents calling setIsLoading after the component unmounts (e.g. during
    // fast navigations), which would trigger a React state-update-on-unmounted
    // component warning.
    let cancelled = false

    async function preload() {
      try {
        await LazyGlobalNavUserMenu.preload()
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    // Fire-and-forget: the void operator signals to the linter that we
    // intentionally don't await this promise inside useEffect (which can't
    // return a Promise). Cleanup is handled via the `cancelled` flag instead.
    void preload()

    return () => {
      cancelled = true
    }
  }, [])

  const onClose = useCallback(() => {
    setOpen(false)
  }, [setOpen])

  const showLoadingState = isLoading || isPending
  const openMenu = open && !showLoadingState

  return (
    <>
      <GlobalNavUserMenuToggle
        owner={owner}
        ref={anchorRef}
        open={open}
        setOpen={setOpen}
        isLoading={open && showLoadingState}
      />
      <Suspense fallback={null}>
        {globalUserMenuProps && (
          <LazyGlobalNavUserMenu
            {...globalUserMenuProps}
            owner={owner}
            anchorRef={anchorRef}
            open={openMenu}
            onClose={onClose}
          />
        )}
      </Suspense>
    </>
  )
}

const LazyGlobalNavUserMenu = lazyWithPreload(async () => {
  const mod = await import('../user-menu/GlobalNavUserMenu')
  return {default: mod.GlobalNavUserMenu}
})
