import {useNavigableRef} from '@github-ui/navigable-ref'
import {lazyWithPreload} from '@github-ui/react-core/lazy-with-preload'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {Suspense, useCallback, useEffect, useState} from 'react'

import type {GlobalNavMenuProps} from '../menu/GlobalNavMenu'
import {GlobalNavMenuToggle} from '../menu/GlobalNavMenuToggle'
import {useTopNavContext} from '../primitives/TopNav'

export function LazyAnchoredGlobalNavMenu() {
  const [open, setOpen] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const anchorRef = useNavigableRef<HTMLButtonElement>()
  const {getPayloadsUrl} = useTopNavContext()
  const payloadsUrl = getPayloadsUrl('nav_menu')

  const {data: menuProps, isPending} = useQuery({
    queryKey: ['global-nav-menu', payloadsUrl],
    queryFn: async () => {
      const response = await verifiedFetchJSON(payloadsUrl)

      if (response.ok) {
        try {
          return (await response.json()) as GlobalNavMenuProps
        } catch {
          throw new Error('Failed to parse nav menu payload.')
        }
      }
      throw new Error('Failed to retrieve nav menu payload.')
    },
  })

  useEffect(() => {
    let cancelled = false

    LazyGlobalNavMenu.preload()
      // eslint-disable-next-line github/no-then
      .then(() => {
        if (!cancelled) {
          setIsLoading(false)
        }
      })
      // eslint-disable-next-line github/no-then
      .catch(() => {
        if (!cancelled) {
          setIsLoading(false)
        }
      })

    return () => {
      cancelled = true
    }
  }, [])

  const onClose = useCallback(() => {
    setOpen(false)
  }, [setOpen])

  const showLoadingState = isLoading || isPending
  const openMenu = open && !showLoadingState
  return (
    <>
      <GlobalNavMenuToggle ref={anchorRef} setOpen={setOpen} open={open} isLoading={open && showLoadingState} />
      <Suspense fallback={null}>
        <LazyGlobalNavMenu returnFocusRef={anchorRef} open={openMenu} onClose={onClose} {...menuProps} />
      </Suspense>
    </>
  )
}

const LazyGlobalNavMenu = lazyWithPreload(async () => {
  const mod = await import('../menu/GlobalNavMenu')
  return {default: mod.GlobalNavMenu}
})
