import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {lazy, Suspense} from 'react'

import {useTopNavContext} from '../primitives/TopNav'
import type {AccountSwitchDialogProps} from '../user-menu/AccountSwitchDialog'

export function LazyAccountSwitchDialog() {
  const {getPayloadsUrl} = useTopNavContext()
  const payloadsUrl = getPayloadsUrl('account_switch_dialog')

  const {data: accountSwitchDialogProps} = useQuery({
    queryKey: ['account-switch-dialog', payloadsUrl],
    queryFn: async () => {
      const response = await verifiedFetchJSON(payloadsUrl)

      if (response.ok) {
        try {
          return (await response.json()) as AccountSwitchDialogProps
        } catch {
          throw new Error('Failed to parse account switch dialog payload.')
        }
      }
      throw new Error('Failed to retrieve account switch dialog payload.')
    },
  })

  return (
    <Suspense fallback={null}>
      {accountSwitchDialogProps && <AccountSwitchDialog {...accountSwitchDialogProps} />}
    </Suspense>
  )
}

const AccountSwitchDialog = lazy(async () => {
  const mod = await import('../user-menu/AccountSwitchDialog')
  return {default: mod.AccountSwitchDialog}
})
