import type {CopilotChatProps} from '@github-ui/copilot-chat/CopilotChat'
import {OpenCopilotChatEvent, subscribeOpenCopilotChat} from '@github-ui/copilot-chat/utils/copilot-chat-events'
import {CopilotChatIntents} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {CopilotImmersivePayload} from '@github-ui/copilot-immersive-v1/routes/payloads'
import {isFeatureEnabled} from '@github-ui/feature-flags'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {GlobalCopilotMenu} from '@github-ui/global-copilot-menu/GlobalCopilotMenu'
import type {ReactPartialAnchorProps} from '@github-ui/react-core/react-partial-anchor'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {CopilotIcon} from '@primer/octicons-react'
import {ButtonGroup} from '@primer/react'
import {clsx} from 'clsx'
import {lazy, Suspense, useEffect, useRef, useState} from 'react'

import {NavLinkItem} from '../../primitives/NavItemLink'
import baseStyles from '../../primitives/styles.module.css'
import {useTopNavContext} from '../../primitives/TopNav'
import {useGlobalNavAnalytics} from '../../utils/Analytics'
import {LazyGlobalNavAgentsMenu} from '../LazyGlobalNavAgentsMenu'
import styles from './CopilotItems.module.css'

export type CopilotItemsProps = {
  show?: boolean
  showAgentsButton?: boolean
  copilotApiUrl?: string | undefined
  copilotChatUrl?: string
}

export function CopilotItems({show, showAgentsButton, copilotApiUrl, copilotChatUrl}: CopilotItemsProps) {
  const {shouldLoadCopilotChat, loadCopilotChat} = useTopNavContext()

  const {sendItemClick} = useGlobalNavAnalytics('COPILOT')
  const isImmersiveEmbedded = isFeatureEnabled('copilot_immersive_embedded')
  const isImmersiveEmbeddedHeaderButton =
    isImmersiveEmbedded && isFeatureEnabled('copilot_immersive_embedded_header_button')

  // Fetch Copilot props - returns different payload type based on the immersive embedded flag
  const {data: copilotChatProps, isPending: isPending} = useQuery({
    enabled: !!copilotChatUrl,
    queryKey: ['copilot-chat', copilotChatUrl, isImmersiveEmbedded],
    queryFn: async () => {
      if (!copilotChatUrl) {
        return null
      }

      const response = await verifiedFetchJSON(copilotChatUrl)

      if (response.ok) {
        try {
          if (isImmersiveEmbedded) {
            return (await response.json()) as CopilotImmersivePayload
          }
          return (await response.json()) as CopilotChatProps
        } catch {
          throw new Error('Failed to parse copilot chat response.')
        }
      }
      throw new Error('Failed to retrieve copilot chat payload.')
    },
  })

  // Initialize a reactPartialAnchor from the Copilot NavLink anchor element
  const anchorRef = useRef<HTMLAnchorElement>(null)
  const [reactPartialAnchor, setReactPartialAnchor] = useState<ReactPartialAnchorProps['reactPartialAnchor']>()
  // Store pending open event to re-dispatch after embedded component loads
  const [pendingOpenEvent, setPendingOpenEvent] = useState<OpenCopilotChatEvent | null>(null)
  useEffect(() => {
    if (anchorRef.current && !reactPartialAnchor) {
      setReactPartialAnchor({
        __wrapperElement: {
          anchor: anchorRef.current,
        },
      } as unknown as ReactPartialAnchorProps['reactPartialAnchor'])
    }
  }, [reactPartialAnchor])

  // Subscribe to open-copilot-chat events to trigger loading.
  useEffect(() => {
    return subscribeOpenCopilotChat(e => {
      loadCopilotChat()
      // Store the event so we can re-dispatch it after the embedded component loads
      setPendingOpenEvent(e)
    })
  }, [loadCopilotChat])

  if (!show) {
    return null
  }

  const shouldUseAgentsHref =
    isFeatureEnabled('copilot_default_to_task_input') &&
    isFeatureEnabled('copilot_redirect_header_button_to_agents') &&
    showAgentsButton

  let analyticsKey = 'COPILOT_CHAT'
  if (isFeatureEnabled('copilot_default_to_task_input')) {
    analyticsKey += '_TASK_BUTTON'
  }
  if (isFeatureEnabled('copilot_default_to_task_input_control_group')) {
    analyticsKey += '_TASK_EXPERIMENT_CONTROL'
  }

  const copilotItemProps = {
    href: shouldUseAgentsHref ? '/copilot/agents' : '/copilot',
    icon: CopilotIcon,
    'aria-label': shouldUseAgentsHref ? 'Navigate to Copilot' : 'Chat with Copilot',
    analyticsKey,
    analyticsSubCategory: 'COPILOT',
    copilotApiUrl,
    ref: anchorRef,
    // When immersive embedded header button is enabled, prevent navigation and let the component handle opening
    onClick: isImmersiveEmbeddedHeaderButton
      ? (e: React.MouseEvent) => {
          e.preventDefault()
          loadCopilotChat()
          // Read any pending references from localStorage (set by "Ask Copilot" buttons elsewhere)
          const storedReferences = copilotLocalStorage.getCurrentReferences(null)
          if (storedReferences && storedReferences.length > 0) {
            copilotLocalStorage.clearCurrentReferences(null)
          }
          setPendingOpenEvent(
            new OpenCopilotChatEvent({
              intent: CopilotChatIntents.conversation,
              source: 'header',
              references: storedReferences ?? undefined,
            }),
          )
        }
      : undefined,
    onMouseEnter: isImmersiveEmbeddedHeaderButton ? loadCopilotChat : undefined,
    onFocus: isImmersiveEmbeddedHeaderButton ? loadCopilotChat : undefined,
  }

  const shouldShowCopilotChat = !isPending && copilotChatProps && reactPartialAnchor

  return (
    <span>
      <ButtonGroup>
        <NavLinkItem {...copilotItemProps} />
        {showAgentsButton ? (
          <LazyGlobalNavAgentsMenu
            copilotApiUrl={copilotApiUrl}
            anchorProps={{
              variant: 'invisible',
              className: clsx(baseStyles.appHeaderButton, styles.AgentsMenu),
              onClick: () => {
                sendItemClick('AGENTS_MENU')
              },
            }}
          />
        ) : (
          <GlobalCopilotMenu
            anchorProps={{
              variant: 'invisible',
              className: clsx(baseStyles.appHeaderButton, styles.CopilotMenu),
              onMouseEnter: loadCopilotChat,
              onFocus: loadCopilotChat,
              onClick: () => {
                loadCopilotChat()
                sendItemClick('COPILOT_MENU')
              },
            }}
          />
        )}
      </ButtonGroup>
      {shouldShowCopilotChat && shouldLoadCopilotChat && typeof window !== 'undefined' ? (
        <Suspense fallback={null}>
          {isImmersiveEmbedded ? (
            <LazyCopilotImmersiveEmbedded
              {...(copilotChatProps as CopilotImmersivePayload)}
              pendingOpenEvent={pendingOpenEvent}
              onPendingEventHandled={() => setPendingOpenEvent(null)}
            />
          ) : (
            <LazyCopilotChat {...(copilotChatProps as CopilotChatProps)} reactPartialAnchor={reactPartialAnchor} />
          )}
        </Suspense>
      ) : null}
    </span>
  )
}

const LazyCopilotChat = lazy(async () => {
  const mod = await import('@github-ui/copilot-chat/CopilotChat')
  return {default: mod.CopilotChat}
})

const LazyCopilotImmersiveEmbedded = lazy(async () => {
  const mod = await import('@github-ui/copilot-immersive-embedded/CopilotImmersiveEmbedded')
  return {default: mod.CopilotImmersiveEmbedded}
})
