// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {GlobalCreateMenu, type GlobalCreateMenuProps} from '@github-ui/global-create-menu'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useRef, useState} from 'react'

import {useTopNavContext} from '../primitives/TopNav'

export function LazyGlobalCreateMenu() {
  const {getPayloadsUrl} = useTopNavContext()
  const payloadsUrl = getPayloadsUrl('create_menu')
  const [isOpen, setIsOpen] = useState(false)
  const anchorRef = useRef<HTMLElement | null>(null)

  const {data: createMenuProps, isPending} = useQuery({
    queryKey: ['global-create-menu', payloadsUrl],
    queryFn: async () => {
      const response = await verifiedFetchJSON(payloadsUrl)

      if (response.ok) {
        try {
          return (await response.json()) as GlobalCreateMenuProps
        } catch {
          throw new Error('Failed to parse create menu payload.')
        }
      }
      throw new Error('Failed to retrieve create menu payload.')
    },
  })

  return (
    <GlobalCreateMenu
      {...createMenuProps}
      isOpen={isOpen && !isPending}
      setIsOpen={setIsOpen}
      anchorRef={anchorRef}
      isLoading={isOpen && isPending}
    />
  )
}
