import {isFeatureEnabled} from '@github-ui/feature-flags'
import {Breadcrumbs} from '@primer/react'
import {FeatureFlags} from '@primer/react/experimental'
import {clsx} from 'clsx'
import React, {useCallback, useEffect, useImperativeHandle, useRef} from 'react'

import {clearRegisteredContextRegion, getContextRegion, registerContextRegionHandler} from '../../global-navigation'
import {useTopNavContext} from '../../primitives/TopNav'
import type {ContextCrumb, ContextRegionActions, CrumbOptions} from '../../types'
import {useGlobalNavAnalytics} from '../../utils/Analytics'
import {getOcticon} from '../../utils/octicons'
import {RepoPicker} from './RepoPicker'
import styles from './styles.module.css'

export function toContextCrumb(crumb: CrumbOptions): ContextCrumb {
  return {
    crumb_type: 'unknown',
    label: crumb.label,
    is_root: false,
    href: crumb.href,
  }
}

export interface ContextRegionProps {
  /** Array of breadcrumb items for the context region */
  crumbs?: ContextCrumb[]

  /** Callback fired when the crumbs are updated */
  onUpdateCrumbs?: (crumbs: ContextCrumb[]) => void

  ref?: React.Ref<ContextRegionActions>
}

export function useRegisterContextRegion(): Partial<ContextRegionProps & React.RefAttributes<ContextRegionActions>> {
  const ref = useRef<ContextRegionActions | null>(null)

  useEffect(() => {
    const {current} = ref

    if (current && getContextRegion({source: 'react', silent: true}) !== current) {
      registerContextRegionHandler(current)
    }

    return () => {
      if (getContextRegion({source: 'react', silent: true}) === current) {
        clearRegisteredContextRegion()
      }
    }
  }, [])

  return {ref}
}

export function ContextRegion({ref, ...props}: ContextRegionProps) {
  const {sendItemClick} = useGlobalNavAnalytics('CONTEXT_REGION')
  const {searchOpen, isSearchPage} = useTopNavContext()
  const {onUpdateCrumbs} = props

  const [crumbs, setCrumbs] = React.useState<ContextCrumb[]>(props.crumbs || [])

  useEffect(() => {
    if (props.crumbs) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setCrumbs(props.crumbs)
    }
  }, [props.crumbs])

  const updateCrumbs = useCallback(
    (updateFn: ContextCrumb[] | ((oldCrumbs: ContextCrumb[]) => ContextCrumb[])) => {
      setCrumbs(prevCrumbs => {
        const newCrumbs = typeof updateFn === 'function' ? updateFn(prevCrumbs) : updateFn
        onUpdateCrumbs?.(newCrumbs)
        return newCrumbs
      })
    },
    [onUpdateCrumbs],
  )

  useImperativeHandle(ref, () => {
    return {
      pushCrumb: (crumb: CrumbOptions) => {
        updateCrumbs(prevCrumbs => [...prevCrumbs, toContextCrumb(crumb)])
      },
      popCrumb: () => {
        updateCrumbs(prevCrumbs => prevCrumbs.slice(0, -1))
      },
      replaceCrumbs: (newCrumbs: CrumbOptions[]) => {
        updateCrumbs(newCrumbs.map(toContextCrumb))
      },
      renameCurrentCrumb: (label: string) => {
        updateCrumbs(prevCrumbs => {
          const lastCrumb = prevCrumbs[prevCrumbs.length - 1]

          if (!lastCrumb) {
            return prevCrumbs
          }

          const oldCrumbs = prevCrumbs.slice(0, -1)
          return [...oldCrumbs, {...lastCrumb, label}]
        })
      },
      replaceCurrentCrumb: (crumb: CrumbOptions) => {
        updateCrumbs(prevCrumbs => {
          if (prevCrumbs.length === 0) {
            return prevCrumbs
          }
          const updatedCrumbs = [...prevCrumbs]
          const lastIndex = updatedCrumbs.length - 1
          updatedCrumbs[lastIndex] = toContextCrumb(crumb)
          return updatedCrumbs
        })
      },
    }
  }, [updateCrumbs])

  if (!crumbs || crumbs.length === 0 || isSearchPage || searchOpen) {
    return null
  }

  const lastCrumbIsRepo = crumbs[crumbs.length - 1]?.crumb_type === 'repository'
  const showRepoPicker = lastCrumbIsRepo && isFeatureEnabled('global_nav_repo_picker_experiment')

  const repositoryPickerRepoCrumb = showRepoPicker ? crumbs.find(crumb => crumb.crumb_type === 'repository') : undefined

  // find this repo's owner crumb so we can find other repos under the same owner
  const ownerCrumb =
    showRepoPicker && repositoryPickerRepoCrumb ? crumbs[crumbs.indexOf(repositoryPickerRepoCrumb) - 1] : undefined

  return (
    <FeatureFlags flags={{primer_react_breadcrumbs_overflow_menu: true}}>
      <Breadcrumbs className={styles.contextRegion} overflow="menu">
        {crumbs.map((crumb, index) => {
          if (ownerCrumb && repositoryPickerRepoCrumb && crumb.crumb_type === 'repository') {
            // when the repo picker experiment is enabled, we don't show the repository crumb in the context region
            return (
              <RepoPicker
                key={repositoryPickerRepoCrumb.label}
                repositoryCrumb={repositoryPickerRepoCrumb}
                ownerCrumb={ownerCrumb}
                onCrumbClick={() => {
                  sendItemClick('CONTEXT_REGION_CRUMB', `position:${index + 1}`)
                }}
              />
            )
          }

          const href = crumb.href || crumb.path
          const isLast = index === crumbs.length - 1
          const Octicon = getOcticon(crumb.octicon)

          return (
            <Breadcrumbs.Item
              key={`${href || crumb.label}`}
              as={href ? 'a' : 'span'}
              href={href}
              className={clsx({
                [styles.contextCrumb]: true,
                [styles.contextCrumbStatic]: !href,
              })}
              onClick={() => {
                sendItemClick('CONTEXT_REGION_CRUMB', `position:${index + 1}`)
              }}
            >
              <span className={isLast ? styles.contextCrumbLast : ''}>{crumb.label}</span>
              {Octicon && <Octicon size={12} className={styles.trailingIcon} />}
            </Breadcrumbs.Item>
          )
        })}
      </Breadcrumbs>
    </FeatureFlags>
  )
}
